def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: A dictionary representing the timedelta in seconds and microseconds.
    :rtype: dict
    """
    if not isinstance(value, timedelta):
        raise ValueError("Input must be of type timedelta")
    return {
        "seconds": value.seconds,
        "microseconds": value.microseconds
    }

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        return value.strftime('%H:%M:%S')
    except (AttributeError, ValueError):
        raise ValueError("Invalid time value provided")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise ValueError("The input value must be an instance of Point.")

    # Assuming Point has attributes x and y
    return {"x": value.x, "y": value.y}

