def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    class TTLCache(lru_cache):
        def __init__(self, maxsize, ttl, timer, typed):
            super().__init__(maxsize, typed)
            self.ttl = ttl
            self.timer = timer
            self.lru_table = {}

        def get(self, key):
            if key in self.lru_table:
                expire_time, value = self.lru_table[key]
                if self.timer() - expire_time < self.ttl:
                    return value
                else:
                    del self.lru_table[key]
            return None

        def set(self, key, value):
            expire_time = self.timer() + self.ttl
            self.lru_table[key] = (expire_time, value)
            super().set(key, value)

        def has_key(self, key):
            return key in self.lru_table and self.get(key) is not None

        def clear(self):
            super().clear()
            self.lru_table.clear()

        def __getitem__(self, key):
            value = self.get(key)
            if value is not None:
                self.set(key, value)
                return value
            raise KeyError(key)

        def __setitem__(self, key, value):
            self.set(key, value)

        def __contains__(self, key):
            return self.has_key(key)

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                if self.typed:
                    key = (args, tuple(kwargs.items()))
                else:
                    key = (tuple(args), tuple(sorted(kwargs.items())))
                if not self.has_key(key):
                    value = func(*args, **kwargs)
                    self[key] = value
                return self[key]
            return wrapper

    return TTLCache(maxsize, ttl, timer, typed)

