from collections import OrderedDict

def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        if maxsize is None:
            maxsize = float('inf')
        elif not isinstance(maxsize, int) or maxsize < 0:
            raise ValueError('maxsize must be None or a positive integer')

        if not isinstance(typed, bool):
            raise TypeError('typed must be a boolean')

        cache = OrderedDict()
        hkey = frozenset if typed else hash

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (hkey(args), hkey(kwargs))
            if key in cache:
                cache.move_to_end(key)
            elif len(cache) >= maxsize:
                cache.popitem(last=False)
            result = func(*args, **kwargs)
            cache[key] = result
            return result

        wrapper.cache_info = lambda: (len(cache), maxsize, cache.popitem(last=False) if cache else (None, None))
        wrapper.cache_clear = lambda: cache.clear()
        return wrapper
    return decorator

from collections import OrderedDict

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        if maxsize is None or maxsize < 1:
            return func

        cache = OrderedDict()
        sentinel = object()

        def wrapper(*args):
            if typed:
                key = (func, args, type(args))
            else:
                key = (func, args)

            if key in cache:
                cache.move_to_end(key)
                return cache[key]
            else:
                result = func(*args)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    if not isinstance(maxsize, int) or maxsize < 1:
        raise ValueError("maxsize must be a positive integer")

    from collections import OrderedDict, defaultdict

    class Node:
        def __init__(self, key, value, freq=1):
            self.key = key
            self.value = value
            self.freq = freq

    cache = OrderedDict()
    freq_cache = defaultdict(OrderedDict)
    min_freq = 1

    def get(key):
        if key not in cache:
            return None

        node = cache[key]
        del cache[key]
        freq_cache[node.freq][key] = Node(key, node.value, node.freq + 1)
        cache[key] = freq_cache[node.freq][key]

        if node.freq == min_freq and not freq_cache[min_freq]:
            min_freq += 1

        return node.value

    def set(key, value):
        nonlocal min_freq
        if key in cache:
            del cache[key]

        if len(cache) >= maxsize:
            evict_key, evict_node = cache.popitem(last=False)
            del freq_cache[evict_node.freq][evict_key]
            if not freq_cache[evict_node.freq]:
                min_freq += 1

        if typed:
            key_type = type(key)
            if key_type not in freq_cache[min_freq]:
                freq_cache[min_freq][key] = Node(key, value)
                cache[key] = freq_cache[min_freq][key]
            else:
                freq_cache[min_freq][key].value = value
                cache[key] = freq_cache[min_freq][key]
        else:
            freq_cache[min_freq][key] = Node(key, value)
            cache[key] = freq_cache[min_freq][key]

        min_freq = 1

    def delete(key):
        if key in cache:
            node = cache[key]
            del cache[key]
            del freq_cache[node.freq][key]
            if not freq_cache[node.freq]:
                min_freq += 1

    def clear():
        nonlocal cache, freq_cache, min_freq
        cache.clear()
        freq_cache.clear()
        min_freq = 1

    def decorated_function(func):
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if not typed:
                key = args

            if key in cache:
                return get(key)

            result = func(*args, **kwargs)
            set(key, result)
            return result

        return wrapper

    return decorated_function

def popitem(self):
    if not self:
        raise KeyError("popitem from empty dictionary")
    key, value = self.popitem()
    return key, value

def setdefault(self, key, default=None):
    if key not in self:
        self[key] = default
    return self.get(key, default)

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    if key in self.data:
        return self.data[key]
    else:
        return default

def cachedmethod(cache, key=None, lock=None):
    if key is None:
        def default_key(func, args, kwds):
            return (func, args, tuple(sorted(kwds.items())))
        key = default_key

    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwds):
            if lock:
                lock.acquire()
            try:
                cache_key = key(func, args, kwds)
                result = cache.get(cache_key, None)
                if result is None:
                    result = func(self, *args, **kwds)
                    cache[cache_key] = result
            finally:
                if lock:
                    lock.release()
            return result
        return wrapper
    return decorator

