def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Step 1: Check if the input is a list
    if not isinstance(classes, list):
        raise ValueError("Input must be a list of classes")

    # Step 2: Check if all elements in the list are classes
    for cls in classes:
        if not callable(cls):
            raise ValueError("All elements in the list must be callable")

    # Step 3: Create a dictionary to store class dependencies
    dependencies = {cls: set(getattr(cls, '__bases__', ())) for cls in classes}

    # Step 4: Identify classes that have no dependencies
    independent_classes = [cls for cls, deps in dependencies.items() if not deps]

    # Step 5: Build the minimal basis
    minimal_basis = []
    visited = set()

    while independent_classes:
        # Take an independent class and add it to the minimal basis
        current_class = independent_classes.pop()
        minimal_basis.append(current_class)
        visited.add(current_class)

        # Update dependencies of other classes
        for other_class, deps in dependencies.items():
            if current_class in deps:
                deps.remove(current_class)
                if not deps and other_class not in visited:
                    independent_classes.append(other_class)

    # Step 6: Return the minimal basis in the order they were added
    return minimal_basis

