class ToCSV:
    def __call__(self, graph: Graph, separator=",", header=None) -> str:
        warnings.warn("to_csv is not used. Convert graph's points to tables using lena.output.ToCSV inside a Lena sequence.", DeprecationWarning)

        def point_to_string(point, separator):
            return separator.join(str(coord) for coord in point)

        lines = []
        if header is not None:
            lines.append(header)

        for point in graph.points:
            if isinstance(point, Iterable):
                point_str = point_to_string(point, separator)
                lines.append(point_str)

        return '\n'.join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise ValueError("coord_name must be a string")

    # Assuming self.errors is a dictionary where keys are coordinate names and values are lists of error indices
    if coord_name not in self.errors:
        raise KeyError(f"No error indices found for coordinate '{coord_name}'")

    return self.errors[coord_name]

def _update_context(self, context):
    if "error" not in context:
        context["error"] = {}

    if getattr(self, "error_E_low", None) is not None:
        context["error"]["x_low"] = {"index": 2}

    if getattr(self, "error", None) is not None:
        context["error"]["other"] = {"index": 1}

    if "value" not in context:
        context["value"] = {}

    # Ensure all fields are dictionaries
    for field in ["error", "value"]:
        if field not in context:
            context[field] = {}
        for key, subcontext in context[field].items():
            if not isinstance(subcontext, dict):
                context[field][key] = {}

def is_fill_request_seq(seq):
    if not seq:
        return False
    if isinstance(seq, FillRequest):
        return True
    if not hasattr(seq, '__iter__'):
        return False
    for item in seq:
        if isinstance(item, FillRequest):
            return True
    return False

