import copy

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def deep_diff(obj1, obj2, current_level):
        if current_level == 0:
            return None

        if isinstance(obj1, dict) and isinstance(obj2, dict):
            result = {}
            for key in obj1:
                if key not in obj2:
                    result[key] = copy.deepcopy(obj1[key])
                elif isinstance(obj1[key], dict) and isinstance(obj2[key], dict):
                    diff = deep_diff(obj1[key], obj2[key], current_level - 1)
                    if diff:
                        result[key] = diff
                elif obj1[key] != obj2[key]:
                    result[key] = obj1[key]
            return result
        elif obj1 != obj2:
            return copy.deepcopy(obj1)
        return None

    return deep_diff(copy.deepcopy(d1), d2, level)

def fill(self, coord, weight=1):
    try:
        if.coord < self.edges[0] or coord >= self.edges[-1]:
            return
        index = bisect.bisect(self.edges, coord)
        self.bins[index - 1] += weight
    except (TypeError, IndexError, ValueError):
        pass

