class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__("\n".join([f"{msg[list(msg.keys())[0]]}: {list(msg.values())[0]}" for msg in messages]))

def _validate_labels(labels: Dict[str, str]) -> None:
    key_pattern = re.compile(r'^[a-zA-Z0-9_$]+$')
    value_pattern = re.compile(r'^[a-zA-Z0-9]+$')

    errors = []

    for key, value in labels.items():
        if not isinstance(key, str) or not key_pattern.match(key):
            errors.append({str(key): "Label key does not match the regex pattern"})
        if not isinstance(value, str) or not value_pattern.match(value):
            errors.append({str(value): "Label value does not match the regex pattern"})

    if errors:
        raise ValidationError(errors)

