def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Safely converts a Kubernetes resource manifest into a default observer schema dict.

    Args:
        manifest_dict (dict): The input dictionary representing a Kubernetes resource.
        first_level (bool, optional): Indicates whether this is the top-level schema.

    Returns:
        dict: A new dictionary with all non-list and non-dict values set to None.
              Identifying fields are copied if first_level is True.
    """
    # Initialize the result dictionary
    observer_schema = {}

    # Iterate through each key in the manifest_dict
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recursively handle nested dictionaries
            observer_schema[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Lists are copied as is
            observer_schema[key] = value
        else:
            # Non-list, non-dict values are set to None
            observer_schema[key] = None

    # If this is the first level, copy identifying fields from the manifest
    if first_level:
        for field in ['apiVersion', 'kind', 'metadata']:
            if field in manifest_dict:
                observer_schema[field] = manifest_dict[field]

    # Return the generated observer schema
    return observer_schema

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for observer in observer_schema:
        if observer in response:
            if observer not in last_applied_manifest:
                last_applied_manifest.append(observer)
            update_last_applied_manifest_list_from_resp(last_applied_manifest[observer], observer_schema[observer], response[observer])
        else:
            raise KeyError(f"Observer {observer} not found in response")
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for field, schema in observer_schema.items():
        if field in response:
            if isinstance(schema, dict):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, response[field]
                )
            else:
                last_applied_manifest[field] = response[field]
        else:
            raise KeyError(f"Observed field '{field}' not present in the Kubernetes response")

def generate_default_observer_schema(app):
    default_schema = {}
    for manifest in app.spec.manifest:
        if 'custom_observer_schema' not in manifest:
            default_schema[manifest['kind']] = {
                'version': manifest['apiVersion'],
                'plurals': manifest.get('plurals', []),
                'names': {
                    'plural': manifest.get('plural', ''),
                    'singular': manifest.get('singular', ''),
                    'kind': manifest.get('kind', ''),
                    'shortNames': manifest.get('shortNames', [])
                }
            }
    return default_schema

from typing import AnyStr, Tuple, Union, Dict, Sequence

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Check if sql is a valid string or bytes
    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be a string or bytes")

    # Check if params is a valid dictionary or sequence
    if not isinstance(params, (dict, Sequence)):
        raise ValueError("params must be a dictionary or sequence")

    # Convert parameters to out-style based on the type
    if isinstance(params, dict):
        out_params = {f":{name}": value for name, value in params.items()}
        formatted_sql = sql.format(**out_params)
    else:
        out_params = [value for value in params]
        formatted_sql = sql.format(*out_params)

    return formatted_sql, out_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be a str or bytes")

    if not isinstance(many_params, Iterable):
        raise ValueError("many_params must be an Iterable")

    out_params: List[Dict[Union[str, int], Any]] if isinstance(next(iter(many_params), {}), dict) else List[Sequence[Any]]

    formatted_sql = sql.replace("?", "%s")

    formatted_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            formatted_params.append({k: v.replace("%", "%%") for k, v in params.items()})
        elif isinstance(params, Sequence):
            formatted_params.append([v.replace("%", "%%") for v in params])
        else:
            raise ValueError("params must be a Mapping or Sequence")

    return formatted_sql, formatted_params

