import zipfile
import os

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError("zip_path does not point to a file")

    result = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                file_name = file_info.filename
                if file_name.endswith('.xml'):
                    base_name = os.path.splitext(file_name)[0]
                    if base_name not in result:
                        result[base_name] = []
                    result[base_name].append(zip_ref.read(file_info))
    except zipfile.BadZipFile:
        raise ValueError("The provided path does not point to a valid zip file")
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the zip file: {e}")

    return result

