def _extract_number_and_supplment_from_issue_element(issue):
    import re
    match = re.match(r'<issue>(\d+)(\s*(suppl|Suppl|spe|Spe)\s*(\d)?\.?)?</issue>', issue)
    if match:
        number = match.group(1)
        suppl = match.group(3)
        suppl_number = match.group(5)
        if suppl_number:
            suppl = suppl + suppl_number
        return number, suppl.strip()
    else:
        raise ValueError("Invalid issue element format")

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expression):
        if isinstance(expression, tuple):
            operator, left, right = expression
            if operator == '&':
                if left == right:
                    return left
                elif (left, right) == (left, ~left | right):
                    return apply_absorption(( '&', left, right ))
                elif (right, left) == (right, left & right):
                    return apply_absorption(( '&', left, right ))
            elif operator == '|':
                if left == right:
                    return left
                elif (left, right) == (left, ~left & right):
                    return apply_absorption(( '|', left, right ))
                elif (right, left) == (right, left | right):
                    return apply_absorption(( '|', left, right ))
        return expression

    return [apply_absorption(exp) for exp in args]

