def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""

    def decorator wrapper(*args, **kwargs):
        if callable(method):
            method(vcs, *args, **kwargs)
        else:
            raise ValueError("The provided method must be callable.")

    return decorator

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Step 1: Define the path for the new OCFL root
    ocfl_root_path = "path/to/new/ocfl/root"

    # Step 2: Create the directory for the OCFL root
    try:
        import os
        os.makedirs(ocfl_root_path, exist_ok=True)
    except OSError as e:
        print(f"Failed to create OCFL root directory: {e}")
        return

    # Step 3: Create the necessary subdirectories
    subdirectories = [
        "v1/storage",
        "v1/storage/heads"
    ]

    for subdir in subdirectories:
        try:
            os.makedirs(os.path.join(ocfl_root_path, subdir), exist_ok=True)
        except OSError as e:
            print(f"Failed to create subdirectory {subdir}: {e}")
            return

    # Step 4: Create the required OCFL configuration file
    config_path = os.path.join(ocfl_root_path, "v1/storage/config.json")
    config_content = {
        "name": "OCFL Storage Root",
        "version": "v1"
    }

    try:
        with open(config_path, 'w') as config_file:
            import json
            json.dump(config_content, config_file, indent=4)
    except IOError as e:
        print(f"Failed to create or write to config file: {e}")
        return

    print("OCFL storage root initialized successfully.")

def validate_version_inventories(self, version_dirs):
    root_inventory = None
    version_inventories = {}
    content_digests_diff = {}

    for version_dir in version_dirs:
        try:
            # Load the inventory for the current version directory
            current_inventory = load_inventory(version_dir)

            # If it's the root inventory, store it
            if version_dir == '1':
                root_inventory = current_inventory
            else:
                version_inventories[version_dir] = current_inventory

                # For each item in the current inventory, check the content digest against the root inventory
                for item, digest in current_inventory.items():
                    root_digest = root_inventory.get(item)
                    if root_digest != digest:
                        content_digests_diff[item] = (digest, root_digest)

        except FileNotFoundError:
            print(f"Inventory file not found for directory: {version_dir}")
        except Exception as e:
            print(f"An error occurred while processing directory {version_dir}: {e}")

    return version_inventories, content_digests_diff

def find_path_type(path):
