def deep_merge_nodes(nodes):
    def merge_node(left, right):
        if not isinstance(right, dict):
            return right
        if isinstance(left, dict):
            for key in right:
                left[key] = merge_node(left.get(key), right[key])
            return left
        return right

    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            merged_dict[key] = merge_node(merged_dict[key], value_node.value)
        else:
            merged_dict[key] = value_node.value

    result = []
    for key, value in merged_dict.items():
        key_node = ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=key)
        value_node = ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=[(k, v) for k, v in value.items()])
        result.append((key_node, value_node))

    return result

