def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        try:
            # Attempt to parse arguments with the current subparser
            namespace, remaining = subparser.parse_known_args(remaining_arguments)
            parsed_arguments[subparser_name] = namespace
            remaining_arguments = remaining
        except SystemExit:
            # Ignore SystemExit raised by argparse and continue with other subparsers
            pass

    return parsed_arguments, remaining_arguments

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:
        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),
    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def is_mapping_node(node):
        return isinstance(node, ruamel.yaml.nodes.MappingNode)

    def deep_merge(left, right):
        if not is_mapping_node(left) or not is_mapping_node(right):
            return right
        merged = left.copy()
        for key, right_value in right.items():
            if key in merged:
                merged[key] = deep_merge(merged[key], right_value)
            else:
                merged[key] = right_value
        return merged

    result = {}
    for key, value in nodes:
        if key.value in result:
            result[key.value] = deep_merge(result[key.value], value)
        else:
            result[key.value] = value

    return [(key, value) for key, value in result.items()]

