def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if number < 0:
        raise ValueError("Number must be non-negative")
    if not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must be a list of single characters")
    if padding is not None and (padding < 0 or not isinstance(padding, int)):
        raise ValueError("Padding must be a non-negative integer or None")

    if number == 0:
        return alphabet[0]

    result = []
    base = len(alphabet)
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    result.reverse()
    if padding is not None:
        result = result[:padding]

    return ''.join(result)

