def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        # Run the git status command to get the list of ignored files
        result = subprocess.run(['git', 'status', '--ignored'], capture_output=True, text=True, check=True)

        # Extract the list of ignored files
        ignored_files = [line.strip() for line in result.stdout.splitlines() if line.startswith('*')]

        # Filter out the files that are in the list of ignored files
        filtered_files = [file for file in ignored_files if file in ignored]

        # Join the filtered files into a single string separated by commas
        return ','.join(filtered_files)
    except subprocess.CalledProcessError as e:
        return f"Error running git command: {e}"
    except Exception as e:
        return f"An unexpected error occurred: {e}"

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        number, unit = frequency.split()
        number = int(number)
        if unit.endswith('s'):
            unit = unit[:-1]
        if unit == 'second':
            return datetime.timedelta(seconds=number)
        elif unit == 'minute':
            return datetime.timedelta(minutes=number)
        elif unit == 'hour':
            return datetime.timedelta(hours=number)
        elif unit == 'day':
            return datetime.timedelta(days=number)
        elif unit == 'week':
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown unit: {unit}")
    except (ValueError, AttributeError):
        raise ValueError(f"Cannot parse frequency: {frequency}")

