def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Step 1: Check for explicit __metaclass__ in the first base class
    if explicit_mc is not None:
        return explicit_mc

    # Step 2: Traverse MRO of each base to find a metaclass
    for base in bases:
        if hasattr(base, "__metaclass__"):
            metaclass = base.__metaclass__
            # Step 3: Check if the metaclass is a valid class that can be instantiated
            if callable(metaclass):
                try:
                    metaclass()
                except TypeError:
                    continue
            return metaclass

    # Step 4: If no metaclass is found among bases, use the first base's type
    return type(bases[0])

class MyDict(dict):
    def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if default is self.__marker:
            if key in self:
                return super().pop(key)
            else:
                raise KeyError(key)
        else:
            if key in self:
                return super().pop(key)
            else:
                return default

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""

    if not self:
        raise KeyError("popitem(): dictionary is empty")

    if not hasattr(self, '_order'):
        self._order = []
        self._counts = {}

    while self._order:
        key = self._order[-1]
        if key in self and self._counts[key] > 0:
            break
        self._order.pop()

    if not self._order:
        raise KeyError("popitem(): dictionary is empty")

    key = self._order.pop()
    value = self[key]
    self._counts[key] -= 1

    if self._counts[key] == 0:
        del self._counts[key]
        del self[key]

    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    with self._lock:
        if not self:
            raise KeyError("popitem from an empty dictionary")
        key, value = self.popitem(last=False)
        return (key, value)

