            in_code_block = False

        if in_code_block:
            result_text.append(char)
            continue

        if char == '<':
            in_tag = True
        elif char == '>':
            in_tag = False
            tags.add(current_tag.lower())
            current_tag = ''
        elif in_tag:
            current_tag += char
            result_text.append(char)

        if replacer and in_tag and current_tag != '':
            result_text.append(replacer(current_tag))
            current_tag = ''

    if replacer:
        result_text.append(''.join(result_text))
    else:
        result_text = ''.join(result_text)

    return tags, result_text

