def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str) or not tag:
        return False
    return tag[0].isalpha() and tag.isalnum()

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}

    children_dict = {}
    for child in node:
        if child.tag in children_dict:
            if not isinstance(children_dict[child.tag], list):
                children_dict[child.tag] = [children_dict[child.tag]]
            children_dict[child.tag].append(child)
        else:
            children_dict[child.tag] = child

    return children_dict

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle == entity_handle:
        return True
    else:
        return False

import requests
from urllib.parse import urlparse

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        parsed_url = urlparse(url)
        if not parsed_url.scheme or not parsed_url.netloc:
            raise ValueError("Invalid URL provided")

        if document_path:
            full_url = f"{url}/{document_path}"
        else:
            full_url = f"{url}/.well-known/nodeinfo"

        response = requests.get(full_url, timeout=5)
        response.raise_for_status()

        return response.json()
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve NodeInfo document: {e}") from e
    except ValueError as e:
        raise Exception(f"Invalid input: {e}") from e

import json
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Attempt to parse JSON format
        data = json.loads(document)
        if "aliases" in data and "subject" in data["aliases"]:
            return data
    except json.JSONDecodeError:
        # If JSON parsing fails, assume XRD format
        for line in document.split('\n'):
            if '<XRD' in line:
                # Use a simple parser for XRD (expected format: <XRD><Link rel="alternate" type="application/json" href="url"/></XRD>)
                for subline in [ln.strip() for ln in line.split('<Link')]:
                    if 'rel="alternate"' in subline and 'type="application/json"' in subline:
                        start = subline.find('href="') + len('href="')
                        end = subline.find('"', start)
                        json_url = subline[start:end]
                        try:
                            json_data = requests.get(json_url).json()
                            if "aliases" in json_data and "subject" in json_data["aliases"]:
                                return json_data
                        except Exception as e:
                            print(f"Failed to fetch or parse JSON from URL: {e}")
    return {}

import requests

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    error = None
    status_code = None
    try:
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, params=data, timeout=timeout, *args, **kwargs)
        else:
            raise ValueError("Unsupported HTTP method")
        status_code = response.status_code
    except requests.exceptions.RequestException as e:
        error = e
    return status_code, error

