class cls:
    @classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file parameter is required")

        try:
            with open(yaml_file, 'r') as file:
                data = yaml.safe_load(file)
                if not data:
                    raise IRValidatorException("No data found in the YAML file")

                # Add required fields check here
                required_fields = {'field1', 'field2', 'field3'}
                missing_fields = required_fields - set(data)
                if missing_fields:
                    raise IRValidatorException(f"Missing required fields: {', '.join(missing_fields)}")

                return data

        except FileNotFoundError:
            raise IRValidatorException(f"File not found: {yaml_file}")
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {e}")

def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The dictionary containing the parser specifications.

    Returns:
        dict: The resolved dictionary with included groups.
    """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    if 'include' not in parser_dict:
        return parser_dict

    include_dict = parser_dict.pop('include')

    for key, value in include_dict.items():
        try:
            resolved_value = self._resolve_value(value)
            parser_dict[key] = resolved_value
        except Exception as e:
            raise ValueError(f"Error resolving include directive for key {key}: {e}")

    return parser_dict

